// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { OrderTicket } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Finance/OrderTicket)

figma.connect(OrderTicket, FIGMA_NODE_URL, {
  props: {
    defaultSide: figma.enum('defaultSide', { 'buy': 'buy', 'sell': 'sell' }),
    card: figma.boolean('card'),
  },
  example: ({ defaultSide, card }) => (
    <OrderTicket defaultSide={defaultSide} card={card}></OrderTicket>
  ),
});
